const fs = require('fs');
const path = require('path');

const calDir = '/workspace/testbed/calendar';

// The event: Onboarding Equipment Setup for contractor
// Current time: 2026-09-08 10:00 (Tuesday)
// Must be done before start of business on next business day: 2026-09-09 09:00 (Wednesday)
// Schedule the event for today afternoon to allow time for setup: 2026-09-08 13:00 - 17:00

const summary = 'Onboarding Equipment Setup - New Contractor (Laptop, VPN, Email)';
const dtstart = '20260908T130000';
const dtend   = '20260908T170000';
const dtstamp = '20260908T100000';
const description = 'High Priority: Set up standard Windows laptop, VPN access, and email for newly onboarded contractor. Must be completed before start of business on 2026-09-09. Requested by Olivia (HR). Setup ticket to be tracked by Priya (IT Lead).';

// Create/update calendars for both olivia.hr.manager and priya.it.lead
const users = ['olivia.hr.manager', 'priya.it.lead'];

const vevent = [
  'BEGIN:VEVENT',
  'SUMMARY:' + summary,
  'DTSTART:' + dtstart,
  'DTEND:' + dtend,
  'DTSTAMP:' + dtstamp,
  'DESCRIPTION:' + description,
  'LOCATION:IT Department',
  'END:VEVENT'
].join('\r\n');

for (const user of users) {
  const filePath = path.join(calDir, user + '.ics');
  let content;
  if (fs.existsSync(filePath)) {
    // Insert event before END:VCALENDAR
    content = fs.readFileSync(filePath, 'utf8');
    content = content.replace('END:VCALENDAR', vevent + '\r\nEND:VCALENDAR');
  } else {
    content = [
      'BEGIN:VCALENDAR',
      'VERSION:2.0',
      'PRODID:-//OfficeBench//testbed//EN',
      vevent,
      'END:VCALENDAR'
    ].join('\r\n');
  }
  fs.writeFileSync(filePath, content);
  console.log('Created event on ' + user + \"'s calendar: \" + filePath);
}
"

