node -e "
const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');

const TESTBED_DIR = '/workspace/testbed';
const db = new Database('/workspace/world.db');

const sender = 'priya.it.lead';
const recipient = 'ethan.it.specialist';
const subject = 'Confirmation: Onboarding Equipment Setup Scheduled for This Afternoon';
const content = \`Hi Ethan,

I'm writing to confirm that the onboarding equipment setup for the new contractor has been scheduled for this afternoon (Tuesday, September 8th) from 1:00 PM to 5:00 PM.

The following items need to be prepared and ready before the contractor's start of business tomorrow morning (Wednesday, September 9th):

  - Standard Windows laptop, configured and ready to use
  - VPN access provisioned and tested
  - Email account created and configured

This is a high-priority request from Olivia in HR. Please ensure all items are set up and verified by end of day today so the contractor can hit the ground running tomorrow.

Let me know if you run into any issues or need additional resources to get this done on time.

Best regards,
Priya
IT Lead\`;

// Build .eml content
const eml = [
  'From: ' + sender + '@company.com',
  'To: ' + recipient + '@company.com',
  'Subject: ' + subject,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=\"utf-8\"',
  '',
  content
].join('\\r\\n');

// Write to both sender and recipient mailboxes
for (const folder of [sender, recipient]) {
  const dir = path.join(TESTBED_DIR, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  const filePath = path.join(dir, subject + '.eml');
  fs.writeFileSync(filePath, eml);
  console.log('Wrote: ' + filePath);
}

// Also insert into ob_emails database for both inboxes
const insert = db.prepare(
  'INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner) VALUES (?, ?, ?, ?, ?, ?, ?)'
);

for (const owner of [sender, recipient]) {
  const emailId = owner + '/' + subject + '.eml';
  insert.run(emailId, sender, sender + '@company.com', recipient + '@company.com', subject, content, owner);
  console.log('DB record created for inbox: ' + owner);
}

console.log('\\nEmail sent successfully!');
"
